public static void ordne(int[] r) {
    for (int i = 1; i < r.length; i++) {
        int j = i;
        while (j > 0 && r[j] < r[j - 1]) {
            int h = r[j];
            r[j] = r[j - 1];
            r[j - 1] = h;
            j--;
        }
    }
}

